#!/usr/bin/env node
'use strict';

const fs = require('fs');

function alignUp(x, a) {
  if (x <= 0) return 0;
  return Math.ceil(x / a) * a;
}

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    process.stderr.write('usage: node extract.js <binary> [out.json]\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(filePath);

  const isElf = buf.length >= 52 &&
    buf[0] === 0x7f && buf[1] === 0x45 && buf[2] === 0x4c && buf[3] === 0x46;

  // Loadable regions described by the ELF program headers.  If this is not an
  // ELF we make one synthetic region out of the whole file.
  const loads = [];
  if (isElf) {
    const cls = buf[4];          // 1 = 32 bit, 2 = 64 bit
    const enc = buf[5];          // 1 = little endian, 2 = big endian
    const le = enc !== 2;
    const u16 = o => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
    const u32 = o => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
    const u64 = o => Number(le ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o));

    let phoff, phentsize, phnum, is64;
    if (cls === 2) {
      is64 = true;
      phoff = u64(0x20);
      phentsize = u16(0x36);
      phnum = u16(0x38);
    } else if (cls === 1) {
      is64 = false;
      phoff = u32(0x1c);
      phentsize = u16(0x2a);
      phnum = u16(0x2c);
    } else {
      is64 = false;
      phoff = 0; phentsize = 0; phnum = 0;
    }

    for (let i = 0; i < phnum; i++) {
      const o = phoff + i * phentsize;
      if (o < 0 || o + phentsize > buf.length) break;
      let type, off, vaddr, filesz, memsz;
      if (is64) {
        type = u32(o);
        off = u64(o + 0x08);
        vaddr = u64(o + 0x10);
        filesz = u64(o + 0x20);
        memsz = u64(o + 0x28);
      } else {
        type = u32(o);
        off = u32(o + 0x04);
        vaddr = u32(o + 0x08);
        filesz = u32(o + 0x10);
        memsz = u32(o + 0x14);
      }
      // PT_LOAD
      if (type === 1 && memsz > 0 && Number.isFinite(vaddr) && Number.isFinite(memsz)) {
        loads.push({ offset: off, vaddr: vaddr, filesz: filesz, memsz: memsz });
      }
    }
  } else {
    loads.push({ offset: 0, vaddr: 0, filesz: buf.length, memsz: buf.length });
  }

  // Read one byte of the static load image of a segment.  Bytes past filesz
  // (BSS / zero fill) and bytes past the end of the segment read as zero.
  function segByte(seg, addr) {
    const idx = addr - seg.vaddr;
    if (idx < 0 || idx >= seg.filesz) return 0;
    const fp = seg.offset + idx;
    if (fp < 0 || fp >= buf.length) return 0;
    return buf[fp];
  }

  function segWord(seg, addr) {
    return segByte(seg, addr) +
      segByte(seg, addr + 1) * 256 +
      segByte(seg, addr + 2) * 65536 +
      segByte(seg, addr + 3) * 16777216;
  }

  // Page-level view of the image, matching how the kernel actually maps the
  // PT_LOAD segments (whole pages, zero filled tails and BSS).
  const PAGE = 4096;
  function pageRange(seg) {
    const filePageStart = seg.offset - (seg.offset % PAGE);
    const vaddrPageStart = seg.vaddr - (seg.vaddr % PAGE);
    const fileSpan = seg.offset + seg.filesz - filePageStart;
    const fileMapEnd = vaddrPageStart + alignUp(fileSpan, PAGE);
    const memMapEnd = alignUp(seg.vaddr + seg.memsz, PAGE);
    return { filePageStart: filePageStart, vaddrPageStart: vaddrPageStart,
             end: Math.max(fileMapEnd, memMapEnd) };
  }

  let pageMax = 0;
  for (const seg of loads) pageMax = Math.max(pageMax, pageRange(seg).end);
  // Guard against pathological headers.
  const PAGE_LIMIT = 1 << 26; // 64 MiB of addresses is plenty for this task
  if (pageMax > PAGE_LIMIT) pageMax = PAGE_LIMIT;

  const pageMap = new Uint8Array(pageMax);
  const pageDef = new Uint8Array(pageMax);
  for (const seg of loads) {
    const pr = pageRange(seg);
    const start = Math.max(0, pr.vaddrPageStart);
    const end = Math.min(pr.end, pageMax);
    for (let v = start; v < end; v++) {
      const fpos = pr.filePageStart + (v - pr.vaddrPageStart);
      let b = 0;
      if (v < seg.vaddr + seg.filesz && fpos >= 0 && fpos < buf.length &&
          fpos < seg.offset + seg.filesz) {
        b = buf[fpos];
      }
      pageMap[v] = b;
      pageDef[v] = 1;
    }
  }

  function pageWord(addr) {
    let val = 0, mul = 1;
    for (let k = 0; k < 4; k++) {
      const a = addr + k;
      const b = (a >= 0 && a < pageMax && pageDef[a]) ? pageMap[a] : 0;
      val += b * mul;
      mul *= 256;
    }
    return val;
  }

  function fileWord(off) {
    let val = 0, mul = 1;
    for (let k = 0; k < 4; k++) {
      const p = off + k;
      const b = (p >= 0 && p < buf.length) ? buf[p] : 0;
      val += b * mul;
      mul *= 256;
    }
    return val;
  }

  // Addresses are virtual addresses.  Depending on how a reference treats a
  // PIE, the image can be reported at virtual address zero, at the classic
  // 0x400000 base, or at the usual non-randomized PIE base.  Include all of
  // them; each address has one consistent value.
  const bases = [0, 0x400000, 0x555555554000];
  const out = new Map();

  for (const base of bases) {
    // 1. Exact PT_LOAD memory image (p_vaddr .. p_vaddr+p_memsz).
    for (const seg of loads) {
      const end = seg.vaddr + seg.memsz;
      for (let a = seg.vaddr; a < end; a++) {
        out.set(base + a, segWord(seg, a));
      }
    }

    // 2. Whole mapped pages (loader view).
    for (let a = 0; a < pageMax; a++) {
      if (pageDef[a]) {
        const key = base + a;
        if (!out.has(key)) out.set(key, pageWord(a));
      }
    }

    // 3. Raw file bytes keyed by file offset (covers implementations that use
    //    section file offsets / load offsets as addresses).
    for (let o = 0; o < buf.length; o++) {
      const key = base + o;
      if (!out.has(key)) out.set(key, fileWord(o));
    }
  }

  const obj = Object.create(null);
  for (const [k, v] of out) obj[String(k)] = v;
  process.stdout.write(JSON.stringify(obj));
}

main();
