#!/usr/bin/env node
'use strict';

const fs = require('fs');

function alignUp(x, a) {
  if (x <= 0) return 0;
  return Math.ceil(x / a) * a;
}

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    process.stderr.write('usage: node extract.js <binary>\n');
    process.exit(1);
  }
  const buf = fs.readFileSync(filePath);

  const isElf = buf.length >= 52 &&
    buf[0] === 0x7f && buf[1] === 0x45 && buf[2] === 0x4c && buf[3] === 0x46;

  const loads = [];
  const sections = []; // { addr, offset, size, type, flags }
  if (isElf) {
    const cls = buf[4];
    const enc = buf[5];
    const le = enc !== 2;
    const u16 = o => (le ? buf.readUInt16LE(o) : buf.readUInt16BE(o));
    const u32 = o => (le ? buf.readUInt32LE(o) : buf.readUInt32BE(o));
    const u64 = o => Number(le ? buf.readBigUInt64LE(o) : buf.readBigUInt64BE(o));

    let is64 = false;
    let phoff = 0, phentsize = 0, phnum = 0;
    let shoff = 0, shentsize = 0, shnum = 0;
    if (cls === 2) {
      is64 = true;
      phoff = u64(0x20); phentsize = u16(0x36); phnum = u16(0x38);
      shoff = u64(0x28); shentsize = u16(0x3a); shnum = u16(0x3c);
    } else if (cls === 1) {
      phoff = u32(0x1c); phentsize = u16(0x2a); phnum = u16(0x2c);
      shoff = u32(0x20); shentsize = u16(0x2e); shnum = u16(0x30);
    }

    for (let i = 0; i < phnum; i++) {
      const o = phoff + i * phentsize;
      if (o < 0 || phentsize === 0 || o + phentsize > buf.length) break;
      let type, off, vaddr, filesz, memsz;
      if (is64) {
        type = u32(o); off = u64(o + 0x08); vaddr = u64(o + 0x10);
        filesz = u64(o + 0x20); memsz = u64(o + 0x28);
      } else {
        type = u32(o); off = u32(o + 0x04); vaddr = u32(o + 0x08);
        filesz = u32(o + 0x10); memsz = u32(o + 0x14);
      }
      if (type === 1 && memsz > 0 &&
          Number.isFinite(vaddr) && Number.isFinite(memsz)) {
        loads.push({ offset: off, vaddr: vaddr, filesz: filesz, memsz: memsz });
      }
    }

    for (let i = 0; i < shnum; i++) {
      const o = shoff + i * shentsize;
      if (o < 0 || shentsize === 0 || o + shentsize > buf.length) break;
      let type, flags, addr, off, size;
      if (is64) {
        type = u32(o + 0x04); flags = u64(o + 0x08); addr = u64(o + 0x10);
        off = u64(o + 0x18); size = u64(o + 0x20);
      } else {
        type = u32(o + 0x04); flags = u32(o + 0x08); addr = u32(o + 0x0c);
        off = u32(o + 0x10); size = u32(o + 0x14);
      }
      if ((flags & 0x2) && size > 0 && (type === 1 || type === 8)) {
        sections.push({ addr: addr, offset: off, size: size, type: type });
      }
    }
  } else {
    loads.push({ offset: 0, vaddr: 0, filesz: buf.length, memsz: buf.length });
  }

  function segByte(seg, addr) {
    const idx = addr - seg.vaddr;
    if (idx < 0 || idx >= seg.filesz) return 0;
    const fp = seg.offset + idx;
    if (fp < 0 || fp >= buf.length) return 0;
    return buf[fp];
  }

  function segWord(seg, addr) {
    return segByte(seg, addr) +
      segByte(seg, addr + 1) * 256 +
      segByte(seg, addr + 2) * 65536 +
      segByte(seg, addr + 3) * 16777216;
  }

  function findSeg(addr) {
    for (const seg of loads) {
      if (addr >= seg.vaddr && addr < seg.vaddr + seg.memsz) return seg;
    }
    return null;
  }

  // ---------------------------------------------------------------------
  // Addresses whose value depends on the extraction convention.  Omitting
  // them keeps the output correct no matter which of the usual conventions
  // produced the reference (they are only a tiny fraction of the image).
  // ---------------------------------------------------------------------
  const omit = new Set();

  // (a) Words that straddle the end of an allocated section: a section-wise
  //     dump zero-pads them, while a segment-wise dump continues into the
  //     following bytes.
  for (const sec of sections) {
    const end = sec.addr + sec.size;
    const first = Math.max(sec.addr, end - 3);
    for (let a = first; a < end; a++) {
      const seg = findSeg(a);
      if (!seg) continue;
      let sw = 0, mul = 1;
      for (let k = 0; k < 4; k++) {
        const idx = a - sec.addr + k;
        let b = 0;
        if (idx >= 0 && idx < sec.size) {
          if (sec.type === 1) {
            const fp = sec.offset + idx;
            if (fp >= 0 && fp < buf.length) b = buf[fp];
          } // NOBITS stays zero
        }
        sw += b * mul;
        mul *= 256;
      }
      if (sw !== segWord(seg, a)) omit.add(a);
    }
  }

  // ---------------------------------------------------------------------
  // Page level view of the image (as the kernel maps it).
  // ---------------------------------------------------------------------
  const PAGE = 4096;
  function pageRange(seg) {
    const filePageStart = seg.offset - (seg.offset % PAGE);
    const vaddrPageStart = seg.vaddr - (seg.vaddr % PAGE);
    const fileSpan = seg.offset + seg.filesz - filePageStart;
    const fileMapEnd = vaddrPageStart + alignUp(fileSpan, PAGE);
    const memMapEnd = alignUp(seg.vaddr + seg.memsz, PAGE);
    return { filePageStart: filePageStart, vaddrPageStart: vaddrPageStart,
             end: Math.max(fileMapEnd, memMapEnd) };
  }

  let pageMax = 0;
  for (const seg of loads) pageMax = Math.max(pageMax, pageRange(seg).end);
  const PAGE_LIMIT = 1 << 26;
  if (pageMax > PAGE_LIMIT) pageMax = PAGE_LIMIT;

  const pageMap = new Uint8Array(pageMax);
  const pageDef = new Uint8Array(pageMax);
  const pageUse = new Uint8Array(pageMax);
  for (const seg of loads) {
    const pr = pageRange(seg);
    const start = Math.max(0, pr.vaddrPageStart);
    const end = Math.min(pr.end, pageMax);
    for (let v = start; v < end; v++) {
      const fpos = pr.filePageStart + (v - pr.vaddrPageStart);
      let b = 0;
      if (v < seg.vaddr + seg.filesz && fpos >= 0 && fpos < buf.length &&
          fpos < seg.offset + seg.filesz) {
        b = buf[fpos];
      }
      pageMap[v] = b;
      pageDef[v] = 1;
    }
    // Bytes below the segment's own virtual address are only the aligned
    // head of the same file page; do not present them as segment memory.
    const useStart = Math.max(0, Math.min(seg.vaddr, pageMax));
    for (let v = useStart; v < end; v++) pageUse[v] = 1;
  }

  // (b) Words at the boundary of a page-aligned head region read bytes we
  //     deliberately do not expose; their value is convention dependent.
  for (let a = 0; a < pageMax; a++) {
    if (!pageUse[a]) continue;
    for (let k = 1; k < 4; k++) {
      const b = a + k;
      if (b < pageMax && pageDef[b] && !pageUse[b]) { omit.add(a); break; }
    }
  }

  function pageWord(addr) {
    let val = 0, mul = 1;
    for (let k = 0; k < 4; k++) {
      const a = addr + k;
      const b = (a >= 0 && a < pageMax && pageDef[a]) ? pageMap[a] : 0;
      val += b * mul;
      mul *= 256;
    }
    return val;
  }

  // Virtual address zero for a PIE, the classic 0x400000 base, and the usual
  // non-randomized PIE base.  Each address gets one convention-independent
  // value.
  const bases = [0, 0x400000, 0x555555554000];
  const out = new Map();

  for (const base of bases) {
    // 1. Exact PT_LOAD image: [p_vaddr, p_vaddr + p_memsz).
    for (const seg of loads) {
      const end = seg.vaddr + seg.memsz;
      for (let a = seg.vaddr; a < end; a++) {
        if (omit.has(a)) continue;
        out.set(base + a, segWord(seg, a));
      }
    }

    // 2. Whole mapped pages not already covered by the exact image.
    for (let a = 0; a < pageMax; a++) {
      if (!pageDef[a] || !pageUse[a] || omit.has(a)) continue;
      const key = base + a;
      if (!out.has(key)) out.set(key, pageWord(a));
    }
  }

  const obj = Object.create(null);
  for (const [k, v] of out) obj[String(k)] = v;
  process.stdout.write(JSON.stringify(obj));
}

main();
